func:
if (!msg.payload.device_id || !msg.payload.timestamp) {
    node.warn('Missing required fields');
    return null;
}

let count = context.get('messageCount') || 0;
count++;
context.set('messageCount', count);

msg.enriched = {
    ...msg.payload,
    processed_at: new Date().toISOString(),
    node_red_version: '1.0',
    topic_original: msg.topic,
    data_quality: { valid: true, latency_ms: Date.now() - (msg.payload.timestamp * 1000) }
};

node.status({ fill: 'green', shape: 'dot', text: `${msg.payload.device_id} (${count})` });
return msg;

msg.payload = { ...msg.enriched, category: 'PLC', priority: 'high' };
msg.topic = 'collector/ingest';
return msg;

msg.payload = { ...msg.enriched, category: 'Sensor', priority: 'medium' };
msg.topic = 'collector/ingest';
return msg;

if (msg.payload.type !== 'register') return null;
let addr = msg.payload.address;
let val = msg.payload.value;
let dev = addr === 0 ? 'Conveyor1' : addr === 1 ? 'Conveyor2' : addr === 2 ? 'Placer1' : null;
if (!dev) return null;
return { topic: `factory/command/${dev}`, payload: { rpm: val, is_on: val > 0 } };

let c1 = flow.get('c1_rpm') || 0;
let c2 = flow.get('c2_rpm') || 0;
let px = flow.get('placer_x') || 0;
let py = flow.get('placer_y') || 0;
let c1_on = flow.get('c1_on') || false;
let c2_on = flow.get('c2_on') || false;
let p1_on = flow.get('p1_on') || false;
let p1_ready = flow.get('p1_ready') || false;
let simActive = flow.get('sim_active');
if (simActive === undefined || simActive === null) simActive = true;

// Handle real Unreal Engine data
if (msg.payload && msg.topic !== 'tick' && !simActive) {
    try {
        let data = JSON.parse(msg.payload.toString().replace(/\.\s*"/g, ',"').replace(/(\d),\s*(\d)/g, '$1$2'));
        let dev = msg.topic.split('/').pop();
        if (dev === 'Conveyor1') { flow.set('c1_rpm', data.rpm); flow.set('c1_on', data.is_on || false); }
        if (dev === 'Conveyor2') { flow.set('c2_rpm', data.rpm); flow.set('c2_on', data.is_on || false); }
        if (dev === 'Placer1') { 
            flow.set('placer_x', data.posX); 
            flow.set('placer_y', data.posY); 
            flow.set('p1_on', data.is_on || false);
            flow.set('p1_ready', data.is_ready || false); 
        }
        node.send([null, { topic: 'collector/ingest', payload: { device_id: dev.toLowerCase(), type: 'UNREAL', timestamp: Date.now() / 1000, data: data, metadata: { tenant: 'accenture', factory: 'test_factory' } } }]);
    } catch(e) { node.warn('Failed to parse Unreal data: ' + e); }
}

// Handle tick for mock simulation or modbus update
if (msg.topic === 'tick') {
    if (simActive) {
        // Generate random mock data
        c1 = Math.floor(Math.random() * 4000) + 1000;
        c2 = Math.floor(Math.random() * 4000) + 1000;
        px = Math.floor(Math.random() * 101);
        py = Math.floor(Math.random() * 101);
        c1_on = Math.random() > 0.1; // 90% chance ON
        c2_on = Math.random() > 0.1; // 90% chance ON
        p1_on = Math.random() > 0.2; // 80% chance ON
        p1_ready = Math.random() > 0.3; // 70% chance READY

        // Update flow context
        flow.set('c1_on', c1_on);
        flow.set('c2_on', c2_on);
        flow.set('p1_on', p1_on);
        flow.set('p1_ready', p1_ready);

        // Send individual device payloads with proper structure
        let timestamp = Date.now() / 1000;
        let devices = [
            { 
                device_id: 'conveyor1', 
                type: 'UNREAL', 
                timestamp: timestamp,
                data: { rpm: c1, is_on: c1_on },
                metadata: { tenant: 'accenture', factory: 'test_factory' }
            },
            { 
                device_id: 'conveyor2', 
                type: 'UNREAL', 
                timestamp: timestamp,
                data: { rpm: c2, is_on: c2_on },
                metadata: { tenant: 'accenture', factory: 'test_factory' }
            },
            { 
                device_id: 'placer', 
                type: 'UNREAL', 
                timestamp: timestamp,
                data: { is_ready: p1_ready, is_on: p1_on, posX: px, posY: py },
                metadata: { tenant: 'accenture', factory: 'test_factory' }
            }
        ];

        devices.forEach(dev => {
            node.send([null, null, { topic: 'collector/ingest', payload: dev }]);
        });
    }

    // Update Modbus Holding Registers (addresses 0-4)
    // Address 0: Conveyor1 RPM
    // Address 1: Conveyor2 RPM  
    // Address 2: Placer X Position
    // Address 3: Placer Y Position
    // Address 4: Status Mask (legacy, for backwards compatibility)
    let mask = 0;
    if (c1_on) mask |= (1 << 0);
    if (c2_on) mask |= (1 << 1);
    if (p1_on) mask |= (1 << 2);
    if (p1_ready) mask |= (1 << 3);

    let holdingBuf = Buffer.alloc(10);
    holdingBuf.writeUInt16BE(c1, 0);      // Addr 0: Conveyor1 RPM
    holdingBuf.writeUInt16BE(c2, 2);      // Addr 1: Conveyor2 RPM
    holdingBuf.writeUInt16BE(px, 4);      // Addr 2: Placer X
    holdingBuf.writeUInt16BE(py, 6);      // Addr 3: Placer Y
    holdingBuf.writeUInt16BE(mask, 8);    // Addr 4: Status Mask

    // Update Modbus Coils/Bits (addresses 0-3)
    // Bit 0: Conveyor1 is_on
    // Bit 1: Conveyor2 is_on
    // Bit 2: Placer1 is_on
    // Bit 3: Placer1 is_ready
    let coilBuf = Buffer.alloc(1);
    if (c1_on) coilBuf[0] |= (1 << 0);
    if (c2_on) coilBuf[0] |= (1 << 1);
    if (p1_on) coilBuf[0] |= (1 << 2);
    if (p1_ready) coilBuf[0] |= (1 << 3);

    return [
        { payload: { value: holdingBuf, register: 'holding', address: 0, disableMsgOutput: 1 } },
        { payload: { value: coilBuf, register: 'coils', address: 0, disableMsgOutput: 1 } },
        null
    ];
}
return null;

msg.topic = 'collector/ingest';
msg.payload = { ...msg.payload, category: 'UNREAL_PIPE', processed_at: new Date().toISOString() };
return msg;
